 	case DCB_OUTPUT_LVDS:
 		if (nv_connector->native_mode &&
 		    (mode->hdisplay > nv_connector->native_mode->hdisplay ||
 		     mode->vdisplay > nv_connector->native_mode->vdisplay))
 			return MODE_PANEL;

 		min_clock = 0;
 		max_clock = 400000;
 		break;
